				/*updateMasterWmDlIntervalsInfoReg*/
				UPDATE BNTCARINFO
				SET 
				    CAR_PERSON_NAME	  = #{CAR_PERSON_NAME}
                   ,CAR_PERSON_TEL	  = #{CAR_PERSON_TEL}
                   ,TON	              = #{TON}
                   ,AFFILIATED_CMPY	  = #{AFFILIATED_CMPY}
                   ,REGISTRATION_DATE	= #{REGISTRATION_DATE}
                   ,AREA	            = #{AREA}
                   ,BIRTH_DATE	      = #{BIRTH_DATE}
                   ,TRANSPORT_CMPY	  = #{TRANSPORT_CMPY}
                   ,WAREHOUSE_CODE	  = #{st_warehouse_code}
                   ,CHANGE_DATE	      = to_char(sysdate,'YYYYMMDD')   
                   ,CHANGE_USER	      = #{st_user_id}
                WHERE CAR_ID = #{CAR_ID}


				/*insertMasterWmDlIntervalsInfoReg*/
				INSERT INTO	BNTCARINFO					
				(									
                    CAR_NO	          
                   ,CAR_PERSON_NAME	  
                   ,CAR_PERSON_TEL	  
                   ,TON	              
                   ,AFFILIATED_CMPY	  
                   ,REGISTRATION_DATE	
                   ,AREA	            
                   ,BIRTH_DATE	      
                   ,TRANSPORT_CMPY	  
                   ,WAREHOUSE_CODE	  
                   ,ADD_DATE	        
                   ,CHANGE_DATE	      
                   ,CHANGE_USER	      
                   ,CAR_ID	 

				)									
				  VALUES(									
                    #{CAR_NO}	          
                   ,#{CAR_PERSON_NAME}	  
                   ,#{CAR_PERSON_TEL}	  
                   ,#{TON}	              
                   ,#{AFFILIATED_CMPY}	  
                   ,#{REGISTRATION_DATE}	
                   ,#{AREA}	            
                   ,#{BIRTH_DATE}	      
                   ,#{TRANSPORT_CMPY}	  
                   ,#{st_warehouse_code}	  
                   , to_char(sysdate,'YYYYMMDD')        
                   , to_char(sysdate,'YYYYMMDD')      
                   ,#{st_user_id}	      
                   ,(SELECT TO_CHAR(SYSDATE,'YYYYMMDD')|| LPAD(COUNT(CAR_ID)+1,8,0)  CAR_ID  FROM BNTCARINFO
                WHERE SUBSTR(CAR_ID,0,8) = TO_CHAR(SYSDATE,'YYYYMMDD')          )    
				)
